CREATE TABLE IF NOT EXISTS dim_customer (
    customer_key bigint GENERATED BY DEFAULT AS IDENTITY,
    customer_id text NOT NULL,
    country text,
    city text,
    district text,
    signup_date date,
    primary_device text,
    marketing_consent boolean,
    valid_from timestamptz NOT NULL,
    valid_to timestamptz NOT NULL,
    is_current boolean NOT NULL,
    PRIMARY KEY (customer_key),
    UNIQUE (customer_id, valid_from)
);

CREATE TABLE IF NOT EXISTS dim_product (
    product_key bigint GENERATED BY DEFAULT AS IDENTITY,
    product_id text NOT NULL,
    name text,
    category text,
    price numeric(12,2),
    is_active boolean,
    valid_from timestamptz NOT NULL,
    valid_to timestamptz NOT NULL,
    is_current boolean NOT NULL,
    PRIMARY KEY (product_key),
    UNIQUE (product_id, valid_from)
);

CREATE TABLE IF NOT EXISTS dim_campaign (
    campaign_key bigint GENERATED BY DEFAULT AS IDENTITY,
    campaign_id text NOT NULL,
    utm_campaign text,
    platform text,
    name text,
    start_date date,
    end_date date,
    PRIMARY KEY (campaign_key)
);

CREATE TABLE IF NOT EXISTS dim_date (
    date_key integer NOT NULL,
    date date NOT NULL,
    week integer NOT NULL,
    month integer NOT NULL,
    is_weekend boolean NOT NULL,
    is_friday_saturday boolean NOT NULL,
    is_ramadan boolean NOT NULL,
    is_eid boolean NOT NULL,
    is_holiday boolean NOT NULL,
    PRIMARY KEY (date_key)
);

